using System.Net;
using System.Text.Json;
using System.Text.Json.Nodes;
using Htt.Host.Api;
using Htt.Host.Api.MasterData;
using Htt.Host.Api.Sales;
using Htt.Host.Api.Accounting;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class RecurringTests:IAsyncLifetime
{
 readonly DatabaseFixture db=new();public async Task InitializeAsync(){await db.InitializeAsync();await S("UPDATE recurring.templates SET state='PAUSED'WHERE state='ACTIVE'");}public Task DisposeAsync()=>db.DisposeAsync();
 Task<object?> S(string sql,params(string,object)[] a)=>db.OwnerScalarAsync(sql,a);
 static Guid Id(JsonElement e)=>e.GetProperty("id").GetGuid();static long V(JsonElement e)=>e.GetProperty("version").GetInt64();static JsonElement E(object x)=>JsonSerializer.SerializeToElement(x);
 async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT ((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@c",("c",db.Company)))!);
 async Task<JsonElement> Expense(HttpClient c)
 {var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Recurring supplier",null));var account=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(@c,@code,'Recurring expenses','EXPENSE')RETURNING id",("c",db.Company),("code",Code())))!;var tax=(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@c AND code='GST'",("c",db.Company)))!;await S("UPDATE core.companies SET gst_registered=true WHERE id=@c",("c",db.Company));return E(new{supplierId=supplier,lines=new[]{new{expenseAccountId=account,description="Rent",net=100,tax=10,taxCodeId=tax}}});}
 async Task<Guid> Template(HttpClient c,JsonElement p,string kind="EXPENSE_BILL",DateOnly? start=null,int max=3,string frequency="DAY",int every=1)
 {var first=start??await Today();return await Create(c,"/recurring/templates",new RecurringTemplateInput("Recurring test",kind,frequency,every,first,first.AddYears(2),max,p));}
 Task<JsonElement> View(HttpClient c,Guid id)=>Get(c,$"/recurring/templates/{id}");Task<JsonElement> Run(HttpClient c,Guid id)=>Get(c,$"/recurring/runs/{id}");
 async Task<JsonElement> Change(HttpClient c,Guid id,string action,JsonElement? p=null,string? key=null)=>await Expect(await Send(c,HttpMethod.Post,$"/recurring/templates/{id}/change",new RecurringChangeInput(action,"Reviewed schedule",p),V(await View(c,id)),key),HttpStatusCode.OK);
 async Task<int> Tick(){await using var con=new NpgsqlConnection(db.Worker);await con.OpenAsync();await using var cmd=new NpgsqlCommand("SELECT recurring.tick()",con);return(int)(await cmd.ExecuteScalarAsync())!;}
 async Task<JsonElement[]> Runs(HttpClient c,Guid id)=> (await Get(c,$"/recurring/runs?templateId={id}")).GetProperty("items").EnumerateArray().ToArray();
 async Task<HttpClient> Reviewer(TestApi api){var staff=await Staff(db,"FINANCE");return api.Authenticated(staff.Subject);}
 async Task<JsonElement> Review(HttpClient c,Guid id,string action,object? evidence=null,string? key=null,long? version=null)=>await Expect(await Send(c,HttpMethod.Post,$"/recurring/runs/{id}/review",new RecurringReviewInput(action,"Independent evidence checked",evidence is null?null:E(evidence)),version??V(await Run(c,id)),key),HttpStatusCode.OK);
 async Task<object> BillEvidence(string? number=null){var today=await Today();return new{supplierInvoice=number??Code(),invoiceDate=today,dueOn=today.AddDays(30),postingDate=today,taxInvoiceReference="verified-current-invoice",taxInvoiceHeldOn=today};}
 [Fact]public async Task Defaults_paused_then_generates_one_immutable_proposal_without_GL_or_GST_effects()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));Assert.Equal(0,await Tick());Assert.Equal("PAUSED",(await View(c,id)).GetProperty("state").GetString());await Change(c,id,"RESUME");Assert.Equal(1,await Tick());Assert.Equal(0,await Tick());var run=Assert.Single(await Runs(c,id));Assert.Equal("DRAFT",run.GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));Assert.True(run.GetProperty("readOnlyEconomicEffect").GetBoolean());}
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]
 public async Task Independent_approval_posts_real_expense_bill_once_and_preserves_AP_GST(string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Expense(c);await S("UPDATE core.companies SET gst_basis=@b WHERE id=@c",("b",basis),("c",db.Company));var id=await Template(c,p);await Change(c,id,"RESUME");await Tick();var run=Assert.Single(await Runs(c,id));using var reviewer=await Reviewer(api);var evidence=await BillEvidence();var key=Code();var posted=await Review(reviewer,Id(run),"APPROVE",evidence,key,V(run));Assert.Equal("APPROVED",posted.GetProperty("state").GetString());Assert.Equal("APPROVED",(await Review(reviewer,Id(run),"APPROVE",evidence,key,V(run))).GetProperty("state").GetString());Assert.Equal(1L,await S("SELECT count(*)FROM purchase.bills WHERE company_id=@c",("c",db.Company)));Assert.Equal(1L,await S("SELECT count(*)FROM platform.outbox_events WHERE company_id=@c AND event_type='purchase.bill_posted'",("c",db.Company)));await FinancialReportAssertions.Check(c);Assert.Equal("CONSISTENT",(await Get(c,"/accounting/reconciliation")).GetProperty("status").GetString());}
 [Fact]public async Task Author_cannot_self_approve_and_revoked_posting_right_cannot_replay_approval()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));await Change(c,id,"RESUME");await Tick();var run=Assert.Single(await Runs(c,id));await Expect(await Send(c,HttpMethod.Post,$"/recurring/runs/{Id(run)}/review",new RecurringReviewInput("APPROVE","Checked",E(await BillEvidence())),V(run)),HttpStatusCode.Forbidden);using var reviewer=await Reviewer(api);var key=Code();var evidence=await BillEvidence();await Review(reviewer,Id(run),"APPROVE",evidence,key,V(run));await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='purchase.expense_bills.post'",("c",db.Company));await Expect(await Send(reviewer,HttpMethod.Post,$"/recurring/runs/{Id(run)}/review",new RecurringReviewInput("APPROVE","Independent evidence checked",E(evidence)),V(run),key),HttpStatusCode.Forbidden);}
 [Fact]public async Task Failed_posting_rolls_back_then_controlled_retry_can_use_actual_evidence()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));await Change(c,id,"RESUME");await Tick();var run=Assert.Single(await Runs(c,id));using var reviewer=await Reviewer(api);var failed=await Review(reviewer,Id(run),"APPROVE",new{});Assert.Equal("FAILED",failed.GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM purchase.bills WHERE company_id=@c",("c",db.Company)));await Review(reviewer,Id(run),"RETRY");Assert.Equal("APPROVED",(await Review(reviewer,Id(run),"APPROVE",await BillEvidence())).GetProperty("state").GetString());}
 [Fact]public async Task Paused_revision_only_affects_future_occurrences_and_old_payload_stays_pinned()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Expense(c);var id=await Template(c,p,start:(await Today()).AddDays(-1));await Change(c,id,"RESUME");Assert.Equal(2,await Tick());var original=(await Runs(c,id))[0];await Change(c,id,"PAUSE");var changed=JsonNode.Parse(p.GetRawText())!;changed["lines"]![0]!["net"]=200;await Change(c,id,"REVISE",E(changed));Assert.Equal(2,(await View(c,id)).GetProperty("revision").GetInt32());Assert.Equal(100,D((await Run(c,Id(original))).GetProperty("payload").GetProperty("lines")[0].GetProperty("net")));}
 [Fact]public async Task Cancellation_rejects_pending_proposals_and_never_deletes_posted_documents()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c),start:(await Today()).AddDays(-1));await Change(c,id,"RESUME");await Tick();var runs=await Runs(c,id);using var reviewer=await Reviewer(api);var posted=await Review(reviewer,Id(runs[0]),"APPROVE",await BillEvidence());Assert.Equal("APPROVED",posted.GetProperty("state").GetString());await Change(c,id,"CANCEL");Assert.Equal("REJECTED",(await Run(c,Id(runs[1]))).GetProperty("state").GetString());Assert.Equal("APPROVED",(await Run(c,Id(runs[0]))).GetProperty("state").GetString());Assert.Equal(1L,await S("SELECT count(*)FROM purchase.bills WHERE company_id=@c",("c",db.Company)));Assert.Equal(0,await Tick());}
 [Fact]public async Task Concurrent_ticks_and_reviews_have_one_effect_and_respect_versions()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));await Change(c,id,"RESUME");Assert.Equal(1,(await Task.WhenAll(Tick(),Tick())).Sum());var run=Assert.Single(await Runs(c,id));using var reviewer=await Reviewer(api);var e=E(await BillEvidence());var responses=await Task.WhenAll(Enumerable.Range(0,2).Select(_=>Send(reviewer,HttpMethod.Post,$"/recurring/runs/{Id(run)}/review",new RecurringReviewInput("APPROVE","Checked",e),V(run))));Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.Conflict);Assert.Equal(1L,await S("SELECT count(*)FROM purchase.bills WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Scheduler_revocation_pauses_without_advancing_or_generating_drafts()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));await Change(c,id,"RESUME");await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='recurring.write'",("c",db.Company));await Tick();var view=await View(c,id);Assert.Equal("PAUSED",view.GetProperty("state").GetString());Assert.Equal(0,view.GetProperty("nextIndex").GetInt32());Assert.Empty(await Runs(c,id));}
 [Fact]public async Task Tenant_and_underlying_permission_filters_apply_before_counts_and_payloads()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));using var other=api.Authenticated(company:db.OtherCompany);await Expect(await other.GetAsync($"/api/v1/recurring/templates/{id}"),HttpStatusCode.NotFound);Assert.Equal(0,(await Get(other,"/recurring/templates")).GetProperty("totalCount").GetInt32());await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='purchase.cost.read'",("c",db.Company));Assert.Empty((await Get(c,"/recurring/templates")).GetProperty("items").EnumerateArray());await Expect(await c.GetAsync($"/api/v1/recurring/templates/{id}"),HttpStatusCode.NotFound);}
 [Theory][InlineData("2024-01-31",1,"2024-02-29")][InlineData("2024-01-31",2,"2024-03-31")][InlineData("2025-01-31",1,"2025-02-28")]
 public async Task Monthly_calendar_remains_anchored_to_original_day(string start,int n,string expected)
 {Assert.Equal(expected,await S("SELECT recurring.due_date(@d::date,'MONTH',@n,1)::text",("d",start),("n",n)));}
 [Fact]public async Task Local_company_date_controls_due_slots_and_catchup_is_bounded()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var today=await Today();var id=await Template(c,await Expense(c),start:today.AddDays(-40),max:100);await Change(c,id,"RESUME");Assert.Equal(25,await Tick());Assert.Equal(16,await Tick());Assert.Equal(0,await Tick());Assert.Equal(41,(await Get(c,$"/recurring/runs?templateId={id}")).GetProperty("totalCount").GetInt32());}
 [Theory][InlineData("NaN")][InlineData("Infinity")][InlineData("-1")][InlineData("1.001")]
 public async Task Nonfinite_negative_and_overprecision_amounts_are_rejected(string amount)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=JsonNode.Parse((await Expense(c)).GetRawText())!;p["lines"]![0]!["net"]=amount;var today=await Today();await Expect(await Send(c,HttpMethod.Post,"/recurring/templates",new RecurringTemplateInput("Bad","EXPENSE_BILL","DAY",1,today,today.AddDays(1),2,E(p))),HttpStatusCode.UnprocessableEntity);}
 [Theory][InlineData("htt_app","recurring.tick()")][InlineData("htt_worker","recurring.review(uuid,bigint,text,jsonb,text)")][InlineData("htt_portal","recurring.template_view(uuid)")]
 public async Task Database_roles_cannot_cross_recurring_boundaries(string role,string fn)
 {Assert.False((bool)(await S("SELECT has_function_privilege(@role,@fn,'EXECUTE')",("role",role),("fn",fn)))!);}
 [Fact]public async Task Finite_maximum_ends_schedule_without_infinite_generation()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c),max:1);await Change(c,id,"RESUME");Assert.Equal(1,await Tick());Assert.Equal("COMPLETED",(await View(c,id)).GetProperty("state").GetString());Assert.Equal(0,await Tick());}
 [Fact]public async Task Invoice_proposal_uses_existing_order_fulfilment_and_cannot_overinvoice()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(db,c,0);await S("UPDATE core.companies SET gst_registered=true WHERE id=@c",("c",db.Company));var p=await Get(c,$"/products/{d.Product}");await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(p.GetProperty("sku").GetString()!,"Recurring service",p.GetProperty("taxCodeId").GetGuid(),ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);var q=await Submitted(c,d.Draft());var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var line=(await Get(c,$"/sales-orders/{order}")).GetProperty("lines")[0].GetProperty("id").GetGuid();var id=await Template(c,E(new{orderId=order,lines=new[]{new{orderLineId=line,quantity=2}}}),"INVOICE",start:(await Today()).AddDays(-1));await Change(c,id,"RESUME");await Tick();var runs=await Runs(c,id);using var reviewer=await Reviewer(api);var version=(await Get(c,$"/sales-orders/{order}/invoiceable")).GetProperty("version").GetInt64();Assert.Equal("APPROVED",(await Review(reviewer,Id(runs[0]),"APPROVE",new{orderVersion=version,fulfilmentReference="Recurring service completed"})).GetProperty("state").GetString());version=(await Get(c,$"/sales-orders/{order}/invoiceable")).GetProperty("version").GetInt64();Assert.Equal("FAILED",(await Review(reviewer,Id(runs[1]),"APPROVE",new{orderVersion=version,fulfilmentReference="Recurring service completed"})).GetProperty("state").GetString());Assert.Equal(1L,await S("SELECT count(*)FROM sales.invoices WHERE company_id=@c",("c",db.Company)));await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Bank_proposal_requires_actual_settlement_and_does_not_initiate_payment()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var expense=await Expense(c);var account=expense.GetProperty("lines")[0].GetProperty("expenseAccountId").GetGuid();var bank=await Create(c,"/bank-accounts",new BankAccountInput(Code(),"Recurring cash","CASH"));var tax=(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@c AND code='FRE'",("c",db.Company)))!;var id=await Template(c,E(new{kind="PAY",bankAccountId=bank,lines=new[]{new{accountId=account,description="Paid expense",net=10,tax=0,taxCodeId=tax,basClass="NON_CAPITAL",cashFlowCategory="OPERATING",recoverableTax=0,inputTaxedPercent=0}}}),"BANK_TRANSACTION");await Change(c,id,"RESUME");await Tick();var run=Assert.Single(await Runs(c,id));using var reviewer=await Reviewer(api);Assert.Equal("FAILED",(await Review(reviewer,Id(run),"APPROVE",new{})).GetProperty("state").GetString());await Review(reviewer,Id(run),"RETRY");var result=await Review(reviewer,Id(run),"APPROVE",new{occurredOn=await Today(),reference=Code(),settledConfirmed=true,noPriorPostingConfirmed=true});Assert.Equal("APPROVED",result.GetProperty("state").GetString());await FinancialReportAssertions.Check(c);}

 [Fact]public async Task Closed_posting_period_rejects_proposal_without_any_financial_effect()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));await Change(c,id,"RESUME");await Tick();var run=Assert.Single(await Runs(c,id));var today=await Today();Assert.Equal(1L,await S("WITH changed AS(UPDATE accounting.periods SET state='CLOSED'WHERE company_id=@c AND starts_on<=@d AND ends_on>@d RETURNING id)SELECT count(*)FROM changed",("c",db.Company),("d",today)));using var reviewer=await Reviewer(api);Assert.Equal("FAILED",(await Review(reviewer,Id(run),"APPROVE",await BillEvidence())).GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));}
 [Theory][InlineData("infinity")][InlineData("2099-01-01T00:00:00")]
 public async Task Approval_cannot_pass_nonfinite_or_non_date_values_to_original_posting_functions(string value)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));await Change(c,id,"RESUME");await Tick();var run=Assert.Single(await Runs(c,id));using var reviewer=await Reviewer(api);var e=JsonSerializer.SerializeToNode(await BillEvidence())!;e["dueOn"]=value;Assert.Equal("FAILED",(await Review(reviewer,Id(run),"APPROVE",e)).GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM purchase.bills WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Late_original_posting_audit_failure_rolls_back_source_and_durable_link_together()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Template(c,await Expense(c));await Change(c,id,"RESUME");await Tick();var run=Assert.Single(await Runs(c,id));await S("CREATE FUNCTION public.recurring_test_audit_failure()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='"+db.Company+"'::uuid AND NEW.action='purchase.bill_posted'THEN RAISE EXCEPTION 'injected audit failure';END IF;RETURN NEW;END$$;CREATE TRIGGER recurring_test_audit BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION public.recurring_test_audit_failure()");try{using var reviewer=await Reviewer(api);Assert.Equal("FAILED",(await Review(reviewer,Id(run),"APPROVE",await BillEvidence())).GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM purchase.bills WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER recurring_test_audit ON platform.audit_events;DROP FUNCTION public.recurring_test_audit_failure()");}}
}
